console.log('=== PR REVIEW WORKFLOW - DATA TRANSFORMATION START ===');

// Get PR files from previous node
const prFiles = $input.all();

// Access webhook data from body
const webhookData = $('trigger_code_review_pipeline').first().json.body;

console.log('Webhook data structure:', JSON.stringify(webhookData, null, 2));

const pullNumber = webhookData.pull_number;
const repoName = webhookData.repo_name;
const username = webhookData.username;
const prTitle = webhookData.pr_title || 'No title';
const prAuthor = webhookData.pr_author || 'Unknown';
const prUrl = webhookData.pr_url || '';

console.log('Pull Number:', pullNumber);
console.log('Repo Name:', repoName);
console.log('Username:', username);
console.log('PR Title:', prTitle);
console.log('PR Author:', prAuthor);
console.log('Number of files changed:', prFiles.length);

// Validate required data
if (!pullNumber || !repoName || !username) {
  console.error('ERROR: Missing required webhook data');
  console.error('pull_number:', pullNumber);
  console.error('repo_name:', repoName);
  console.error('username:', username);
  throw new Error('Missing required fields from webhook');
}

// Validate PR files
if (prFiles.length === 0) {
  console.error('ERROR: No files received from GitHub API');
  throw new Error('No files to review');
}

// Construct the review prompt
let changesText = `Pull Request: ${prTitle}\n`;
changesText += `Author: ${prAuthor}\n`;
changesText += `Repository: ${username}/${repoName}\n\n`;
changesText += "Please review the following pull request changes:\n\n";

let totalAdditions = 0;
let totalDeletions = 0;

for (let i = 0; i < prFiles.length; i++) {
  const fileData = prFiles[i].json;

  console.log(`\n--- Processing File ${i + 1}/${prFiles.length} ---`);
  console.log('Filename:', fileData.filename);
  console.log('Status:', fileData.status);
  console.log('Additions:', fileData.additions);
  console.log('Deletions:', fileData.deletions);
  console.log('Has patch:', !!fileData.patch);

  changesText += `File: ${fileData.filename}\n`;
  changesText += `Status: ${fileData.status}\n`;
  changesText += `Changes: +${fileData.additions} -${fileData.deletions}\n`;

  totalAdditions += fileData.additions;
  totalDeletions += fileData.deletions;

  if (fileData.patch) {
    console.log('Patch length (chars):', fileData.patch.length);
    changesText += `\nDiff:\n${fileData.patch}\n`;
  } else {
    console.log('Warning: No patch data available for this file');
  }
  changesText += "\n---\n\n";
}

console.log('\n=== PR SUMMARY ===');
console.log('Total additions:', totalAdditions);
console.log('Total deletions:', totalDeletions);
console.log('Total changes text length:', changesText.length);

// Check if prompt is too long (Cerebras context limit consideration)
if (changesText.length > 100000) {
  console.warn('WARNING: Prompt is very long (' + changesText.length + ' chars)');
  console.warn('Consider implementing chunking or summarization for large PRs');
}

// Construct Cerebras API payload
const cerebrasPayload = {
  model: "llama3.1-8b",
  messages: [
    {
      role: "system",
      content: "You are an expert code reviewer. Provide constructive feedback on code changes, focusing on potential bugs, security issues, performance concerns, and best practices. Be concise and actionable."
    },
    {
      role: "user",
      content: changesText
    }
  ],
  temperature: 0.3,
  max_tokens: 2000,
  top_p: 1,
  stream: false
};

console.log('\n=== CEREBRAS PAYLOAD CONSTRUCTED ===');
console.log('Model:', cerebrasPayload.model);
console.log('Temperature:', cerebrasPayload.temperature);
console.log('Max tokens:', cerebrasPayload.max_tokens);
console.log('Number of messages:', cerebrasPayload.messages.length);
console.log('System prompt length:', cerebrasPayload.messages[0].content.length);
console.log('User message length:', cerebrasPayload.messages[1].content.length);

const output = {
  json: {
    cerebrasPayload: cerebrasPayload,
    pullNumber: pullNumber,
    repoName: repoName,
    username: username,
    prTitle: prTitle,
    prAuthor: prAuthor,
    prUrl: prUrl,
    stats: {
      filesChanged: prFiles.length,
      totalAdditions: totalAdditions,
      totalDeletions: totalDeletions,
      promptLength: changesText.length
    }
  }
};

console.log('\n=== OUTPUT PREPARED ===');
console.log('Output keys:', Object.keys(output.json));
console.log('Stats:', JSON.stringify(output.json.stats, null, 2));
console.log('PR URL:', prUrl);
console.log('=== DATA TRANSFORMATION COMPLETE ===\n');

return output;

console.log('=== WEBHOOK DATA RECEIVED ===');
const webhookData = $input.first().json;
console.log('Full webhook data:', JSON.stringify(webhookData, null, 2));
console.log('pull_number:', webhookData.pull_number);
console.log('repo_name:', webhookData.repo_name);
console.log('username:', webhookData.username);
console.log('=== END WEBHOOK DATA ===');

return [$input.first()];

console.log('=== COMBINE CEREBRAS RESPONSE WITH PR DATA ===');

// Get Cerebras response (it's an array)
const cerebrasResponseArray = $input.first().json;
const cerebrasResponse = Array.isArray(cerebrasResponseArray) 
  ? cerebrasResponseArray[0] 
  : cerebrasResponseArray;

console.log('Cerebras response received');
console.log('- Model:', cerebrasResponse.model);
console.log('- Response ID:', cerebrasResponse.id);

// Validate Cerebras response
if (!cerebrasResponse.choices || cerebrasResponse.choices.length === 0) {
  console.error('ERROR: No choices in Cerebras response');
  throw new Error('Invalid Cerebras response');
}

// Extract the review content
const reviewContent = cerebrasResponse.choices[0].message.content;
console.log('- Review length:', reviewContent.length, 'characters');

// Log token usage
if (cerebrasResponse.usage) {
  console.log('\n=== TOKEN USAGE ===');
  console.log('- Prompt tokens:', cerebrasResponse.usage.prompt_tokens);
  console.log('- Completion tokens:', cerebrasResponse.usage.completion_tokens);
  console.log('- Total tokens:', cerebrasResponse.usage.total_tokens);
}

// Log timing info
if (cerebrasResponse.time_info) {
  console.log('\n=== TIMING INFO ===');
  console.log('- Total time:', cerebrasResponse.time_info.total_time.toFixed(3), 'seconds');
  console.log('- Completion time:', cerebrasResponse.time_info.completion_time.toFixed(3), 'seconds');
}

// Get PR metadata from the transform node
console.log('\n=== RETRIEVING PR METADATA ===');

let prData = $('organize_code_changes_for_ai').first().json;
  console.log('✓ Found PR data from organize_code_changes_for_ai node');


console.log('PR data keys:', Object.keys(prData));

// Extract PR metadata
const pullNumber = prData.pullNumber;
const repoName = prData.repoName;
const username = prData.username;
const prTitle = prData.prTitle;
const prAuthor = prData.prAuthor;
const prUrl = prData.prUrl;
const stats = prData.stats;

console.log('\n=== PR INFORMATION ===');
console.log('- PR Number:', pullNumber);
console.log('- Repository:', `${username}/${repoName}`);
console.log('- Title:', prTitle);
console.log('- Author:', prAuthor);
console.log('- Files Changed:', stats.filesChanged);
console.log('- Lines Added:', stats.totalAdditions);
console.log('- Lines Deleted:', stats.totalDeletions);

// Validate required data
if (!username || !repoName || !pullNumber) {
  console.error('ERROR: Missing required PR metadata');
  console.error('username:', username);
  console.error('repoName:', repoName);
  console.error('pullNumber:', pullNumber);
  throw new Error('Missing required PR metadata');
}

// Format the GitHub comment with rich details
const commentBody = `## 🤖 AI Code Review

${reviewContent}

---

<details>
<summary>📊 <strong>Review Statistics</strong></summary>

**Pull Request Details:**
- **Title**: ${prTitle}
- **Author**: [@${prAuthor}](https://github.com/${prAuthor})
- **PR**: [#${pullNumber}](${prUrl})

**Changes:**
- 📝 **Files Changed**: ${stats.filesChanged}
- ➕ **Lines Added**: ${stats.totalAdditions}
- ➖ **Lines Deleted**: ${stats.totalDeletions}
- 📦 **Total Changes**: ${stats.totalAdditions + stats.totalDeletions} lines

**AI Model:**
- 🤖 **Model**: ${cerebrasResponse.model}
- 🎯 **Tokens Used**: ${cerebrasResponse.usage.total_tokens.toLocaleString()} tokens
  - Prompt: ${cerebrasResponse.usage.prompt_tokens.toLocaleString()}
  - Completion: ${cerebrasResponse.usage.completion_tokens.toLocaleString()}
- ⚡ **Processing Time**: ${cerebrasResponse.time_info.total_time.toFixed(2)}s
- 📅 **Generated**: ${new Date().toLocaleString('en-US', { 
    timeZone: 'Africa/Cairo', 
    dateStyle: 'full', 
    timeStyle: 'short' 
  })}

</details>

---

<sub>🤖 Powered by [Cerebras AI](https://cerebras.ai/) • 🔧 Automated via [n8n](https://n8n.io/) • 🌐 [View Workflow](${prUrl})</sub>`;

// Build GitHub API URL
const githubApiUrl = `https://api.github.com/repos/${username}/${repoName}/issues/${pullNumber}/comments`;

console.log('\n=== GITHUB COMMENT PREPARED ===');
console.log('- API URL:', githubApiUrl);
console.log('- Comment length:', commentBody.length, 'characters');
console.log('- Preview:', commentBody.substring(0, 150) + '...');

// Prepare the output for GitHub API
const githubPayload = {
  body: commentBody
};

console.log('\n=== PAYLOAD PREPARED ===');
console.log('- Payload is valid JSON:', typeof githubPayload === 'object');
console.log('- Body field exists:', !!githubPayload.body);

console.log('=== PROCESSING COMPLETE ===\n');

// FIXED: Everything must be inside the json property
return {
  json: {
    body: commentBody,
    url: githubApiUrl,
    pullNumber: pullNumber,
    repoName: repoName,
    username: username,
    metadata: {
      model: cerebrasResponse.model,
      tokens: cerebrasResponse.usage.total_tokens,
      processingTime: cerebrasResponse.time_info.total_time,
      stats: stats
    }
  }
};
